INSERT INTO lessons (lesson_id,title,mr_title,category,minutes,level,body,mr_body,sort_order) VALUES
(1,'Start your small business','तुमचा छोटा व्यवसाय सुरू करा','Getting started',5,'Beginner','Begin with one product or service you can make consistently. Identify who might buy it, what problem it solves, and how you will reach customers. Start small, ask for feedback, and improve.','तुम्ही नियमितपणे तयार करू शकता असे एक उत्पादन किंवा सेवा निवडा. कोण खरेदी करेल, त्यांना काय उपयोग होईल आणि ग्राहकांपर्यंत कसे पोहोचाल हे ठरवा. छोट्या प्रमाणात सुरुवात करा आणि ग्राहकांचा अभिप्राय घ्या.',1),
(2,'Set a fair selling price','योग्य विक्री किंमत ठरवा','Money skills',4,'Beginner','Add the cost of materials, packaging, transport and your time. Compare similar products in your area, then choose a price that covers your costs and leaves a reasonable profit.','साहित्य, पॅकिंग, वाहतूक आणि तुमच्या वेळेचा खर्च जोडा. परिसरातील समान उत्पादनांच्या किंमती तपासा. खर्च भरून निघेल आणि योग्य नफा मिळेल अशी किंमत ठरवा.',2),
(3,'Promote products online','उत्पादनांची ऑनलाइन जाहिरात करा','Digital skills',6,'Beginner','Use a clear product photo, a short description, the price and a way to contact you. Ask permission before sharing anyone’s photo or personal details. Never promise a result you cannot guarantee.','उत्पादनाचा स्पष्ट फोटो, छोटी माहिती, किंमत आणि संपर्काची पद्धत द्या. इतरांचा फोटो किंवा वैयक्तिक माहिती शेअर करण्यापूर्वी परवानगी घ्या. खात्री नसलेली हमी देऊ नका.',3),
(4,'Build customer trust','ग्राहकांचा विश्वास जिंका','Customer care',5,'Beginner','Reply politely, explain delivery timelines, keep your promises, and handle complaints calmly. Record orders and payments so you can check details later.','नम्रपणे उत्तर द्या, डिलिव्हरीची वेळ स्पष्ट सांगा आणि दिलेले वचन पाळा. तक्रारी शांतपणे हाताळा. ऑर्डर आणि पेमेंटची नोंद ठेवा.',4)
INSERT INTO lessons (lesson_id,title,mr_title,category,minutes,level,body,mr_body,sort_order) VALUES
(5,'Check whether customers want your idea','ग्राहकांना तुमची कल्पना हवी आहे का ते तपासा','Getting started',6,'Beginner','Talk with five likely customers before investing much money. Ask what they currently buy, what is difficult, and what would make them try your product. Listen and improve your offer.','जास्त पैसे गुंतवण्यापूर्वी संभाव्य पाच ग्राहकांशी बोला. ते काय घेतात, त्यांना कोणती अडचण येते आणि तुमचे उत्पादन वापरण्यास काय प्रवृत्त करेल हे विचारा. ऐका आणि तुमची ऑफर सुधारा.',5),
(6,'Describe your ideal customer','तुमचा योग्य ग्राहक ओळखा','Getting started',5,'Beginner','Write down who needs your product, where they shop, and what matters to them: price, convenience, quality or local ingredients. A clear customer picture helps you choose products and promotion.','तुमच्या उत्पादनाची कोणाला गरज असेल, ते कुठे खरेदी करतात आणि त्यांच्यासाठी काय महत्त्वाचे आहे हे लिहा. ग्राहक स्पष्ट समजल्याने उत्पादन आणि जाहिरात ठरवता येते.',6),
(7,'Keep simple daily money records','दररोजचा साधा आर्थिक हिशोब ठेवा','Money skills',5,'Use a notebook to record each sale, expense, date and payment method. Keep business money separate from household money when possible. Review totals weekly.','प्रत्येक विक्री, खर्च, तारीख आणि पेमेंटची पद्धत वहीत लिहा. शक्य असल्यास व्यवसायाचे पैसे घरखर्चापासून वेगळे ठेवा. आठवड्याला एकूण तपासा.',7),
(8,'Understand sales, costs and profit','विक्री, खर्च आणि नफा समजून घ्या','Money skills',6,'Sales are money received from customers. Costs are what you spend to make and deliver products. Profit is sales minus all costs. Count your time, transport, packaging and small fees.','ग्राहकांकडून मिळालेली रक्कम म्हणजे विक्री. उत्पादन आणि वितरणासाठी केलेला खर्च म्हणजे खर्च. सर्व खर्च वजा केल्यावर उरते तो नफा. वेळ, वाहतूक, पॅकिंग आणि शुल्कही मोजा.',8),
(9,'Find your break-even point','खर्च भरून निघण्याचा टप्पा शोधा','Money skills',7,'Add fixed costs for the period. Divide fixed costs by the amount each item contributes after variable costs to estimate how many items you need to sell before profit. Check your assumptions.','त्या कालावधीचे स्थिर खर्च जोडा. प्रत्येक वस्तूच्या किंमतीतून बदलता खर्च वजा करून उरलेल्या रकमेत स्थिर खर्च भागा. नफा होण्यापूर्वी किती वस्तू विकाव्या लागतील याचा अंदाज मिळेल.',9),
(10,'Plan a small first batch','पहिली छोटी उत्पादन फेरी ठरवा','Product & operations',5,'Beginner','Make a small quantity based on likely orders and shelf life. List materials, time, packaging and delivery steps. Small batches reduce waste and help you learn before scaling up.','संभाव्य ऑर्डर आणि टिकण्याचा कालावधी पाहून सुरुवातीला कमी प्रमाणात तयार करा. साहित्य, वेळ, पॅकिंग आणि वितरणाच्या पायऱ्या लिहा. छोट्या फेरीमुळे वाया जाणे कमी होते.',10),
(11,'Package products clearly and safely','उत्पादन सुरक्षित आणि स्पष्ट पॅक करा','Product & operations',5,'Choose packaging that protects the product in storage and travel. Add a clear name, quantity and contact details. Follow applicable local food-safety and labelling requirements for food items.','साठवण आणि वाहतुकीत उत्पादन सुरक्षित राहील असे पॅकिंग निवडा. नाव, प्रमाण आणि संपर्क माहिती लिहा. खाद्यपदार्थांसाठी लागू स्थानिक अन्नसुरक्षा आणि लेबल नियम पाळा.',11),
(12,'Take a useful product photo','उत्पादनाचा उपयुक्त फोटो घ्या','Digital skills',4,'Wipe the camera lens, use daylight and a simple background, and show the whole product. Take a close-up for details. Check that colour and size look true.','कॅमेऱ्याची लेन्स पुसा, नैसर्गिक प्रकाश आणि साधी पार्श्वभूमी वापरा. पूर्ण उत्पादन आणि तपशीलाचा जवळचा फोटो घ्या. रंग आणि आकार खरे दिसतात का तपासा.',12),
(13,'Write a clear WhatsApp product message','WhatsApp साठी स्पष्ट उत्पादन संदेश लिहा','Digital skills',5,'Include the product name, one benefit, price, size, availability, delivery area and how to order. Keep it short and send updates only to people who expect them.','उत्पादनाचे नाव, एक वैशिष्ट्य, किंमत, आकार, उपलब्धता, वितरणाचे ठिकाण आणि ऑर्डरची पद्धत द्या. संदेश छोटा ठेवा आणि अपडेट अपेक्षित असलेल्यांनाच पाठवा.',13),
(14,'Use digital payments safely','डिजिटल पेमेंट सुरक्षितपणे वापरा','Digital skills',6,'Check payment in your own bank or UPI app before handing over an order. A screenshot is not proof of credit. Never share your UPI PIN or one-time password.','ऑर्डर देण्यापूर्वी तुमच्या बँक किंवा UPI अॅपमध्ये पेमेंट जमा झाले का तपासा. स्क्रीनशॉट हा पुरावा नाही. UPI PIN किंवा OTP कुणालाही सांगू नका.',14),
(15,'Manage orders and delivery promises','ऑर्डर आणि वितरणाचे वचन सांभाळा','Customer care',5,'Record each customer, item, quantity, agreed price, payment status and delivery date. Confirm details before accepting. If delayed, contact the customer early and agree on a new time.','ग्राहक, वस्तू, प्रमाण, किंमत, पेमेंट स्थिती आणि वितरण तारीख लिहा. ऑर्डर स्वीकारण्यापूर्वी तपशील निश्चित करा. उशीर झाल्यास ग्राहकाला लवकर कळवा.',15),
(16,'Invite feedback and encourage repeat orders','अभिप्राय मागा आणि पुन्हा ऑर्डर मिळवा','Customer care',4,'After delivery, ask one short question about the product and service. Thank the customer and note useful feedback. With permission, tell satisfied customers when it is available again.','वितरणानंतर उत्पादन आणि सेवेबद्दल एक छोटा प्रश्न विचारा. आभार माना आणि उपयोगी अभिप्राय लिहा. परवानगी घेऊन उत्पादन पुन्हा उपलब्ध झाल्यावर ग्राहकांना कळवा.',16),
(17,'Track stock and avoid waste','साठा नोंदवा आणि वाया जाणे टाळा','Product & operations',5,'Record what you make, sell and have left. Check stock before promising delivery. For products that expire, use older stock first and plan production around realistic demand.','किती तयार केले, विकले आणि उरले याची नोंद ठेवा. वितरणाची तारीख सांगण्यापूर्वी साठा तपासा. मुदत संपणाऱ्या उत्पादनांत जुना साठा आधी वापरा.',17),
(18,'Choose one measurable business goal','मोजता येईल असे एक व्यवसाय ध्येय ठरवा','Getting started',4,'Choose one goal for the next month, such as speaking with ten customers or completing five paid orders. Write the number and date, review what worked, and choose your next step.','पुढील महिन्यासाठी एक ध्येय ठरवा, जसे दहा ग्राहकांशी बोलणे किंवा पाच सशुल्क ऑर्डर पूर्ण करणे. संख्या आणि तारीख लिहा, आढावा घेऊन पुढचे पाऊल निवडा.',18)
INSERT INTO quiz_questions (question_id,question_en,question_mr,options_en,options_mr,correct_option,explanation_en,explanation_mr) VALUES
(1,'What should you include when calculating product cost?','उत्पादनाचा खर्च मोजताना काय समाविष्ट करावे?',JSON_ARRAY('Only materials','Materials, packaging and other expenses','Only the selling price'),JSON_ARRAY('फक्त साहित्य','साहित्य, पॅकिंग आणि इतर खर्च','फक्त विक्री किंमत'),1,'Include all relevant costs so you do not underprice your product.','सर्व संबंधित खर्च जोडा, म्हणजे किंमत खूप कमी ठेवली जाणार नाही.'),
(2,'Which product post is most helpful to customers?','ग्राहकांसाठी कोणती पोस्ट अधिक उपयुक्त आहे?',JSON_ARRAY('A photo with no details','A clear photo, description and price','An unverified claim'),JSON_ARRAY('माहिती नसलेला फोटो','स्पष्ट फोटो, माहिती आणि किंमत','पडताळणी नसलेला दावा'),1,'Clear and accurate details help customers make informed decisions.','स्पष्ट आणि अचूक माहितीमुळे ग्राहक योग्य निर्णय घेऊ शकतात.'),
(3,'What is profit?','नफा म्हणजे काय?',JSON_ARRAY('Revenue minus expenses','Expenses plus revenue','Number of customers'),JSON_ARRAY('उत्पन्न वजा खर्च','खर्च अधिक उत्पन्न','ग्राहकांची संख्या'),0,'Profit is the money left after expenses are subtracted from revenue.','उत्पन्नातून खर्च वजा केल्यावर उरलेली रक्कम म्हणजे नफा.'),
(4,'What should you do before sharing a customer’s personal details?','ग्राहकाची वैयक्तिक माहिती शेअर करण्यापूर्वी काय करावे?',JSON_ARRAY('Share it publicly','Ask for permission','Send it to everyone'),JSON_ARRAY('सार्वजनिकपणे शेअर करा','परवानगी घ्या','सर्वांना पाठवा'),1,'Respect privacy and ask permission before sharing personal information.','वैयक्तिक माहिती शेअर करण्यापूर्वी परवानगी घ्या आणि गोपनीयतेचा आदर करा.')
INSERT INTO quiz_questions (question_id,question_en,question_mr,options_en,options_mr,correct_option,explanation_en,explanation_mr) VALUES
(5,'What is a useful way to test a new business idea?','नवीन व्यवसाय कल्पना तपासण्याचा चांगला मार्ग कोणता?',JSON_ARRAY('Make a large batch immediately','Ask likely customers what they need','Choose without checking demand'),JSON_ARRAY('लगेच मोठ्या प्रमाणात तयार करा','संभाव्य ग्राहकांशी बोलून गरज समजून घ्या','मागणी न तपासता निवडा'),1,'Early customer conversations help improve an idea before spending much.','सुरुवातीच्या ग्राहक संवादातून जास्त खर्चापूर्वी कल्पना सुधारता येते.'),
(6,'Why identify a target customer?','लक्ष्य ग्राहक ओळखणे का उपयोगी आहे?',JSON_ARRAY('To decide whom the product serves','To avoid listening to customers','To guarantee profit'),JSON_ARRAY('उत्पादन कोणासाठी आहे हे ठरवण्यासाठी','ग्राहकांचे ऐकणे टाळण्यासाठी','नफा निश्चित करण्यासाठी'),0,'Knowing whom you serve helps shape the product and message.','कोणासाठी उत्पादन आहे हे समजल्याने उत्पादन आणि संदेश योग्य बनतात.'),
(7,'What belongs in a simple daily business record?','दैनंदिन व्यवसाय नोंदीत काय लिहावे?',JSON_ARRAY('Sales and expenses with dates','Only your biggest sale','Household plans only'),JSON_ARRAY('तारखेसह विक्री आणि खर्च','फक्त सर्वात मोठी विक्री','फक्त घराचे नियोजन'),0,'Dated records help you review cash and catch missed payments.','तारखेसह नोंदीमुळे पैसे तपासता येतात आणि बाकी पेमेंट लक्षात येते.'),
(8,'How do you estimate profit?','नफ्याचा अंदाज कसा काढाल?',JSON_ARRAY('Sales minus all costs','Sales plus costs','Number of products made'),JSON_ARRAY('विक्री वजा सर्व खर्च','विक्री अधिक खर्च','तयार केलेल्या वस्तूंची संख्या'),0,'Subtract all relevant costs from sales to estimate profit.','नफ्याचा अंदाज घेण्यासाठी विक्रीतून सर्व संबंधित खर्च वजा करा.'),
(9,'When does a business reach break-even?','व्यवसाय खर्च भरून निघण्याच्या टप्प्यावर कधी पोहोचतो?',JSON_ARRAY('When sales cover costs','When every item is free','Before costs are counted'),JSON_ARRAY('विक्रीतून खर्च भरून निघतात तेव्हा','प्रत्येक वस्तू मोफत असते तेव्हा','खर्च मोजण्यापूर्वी'),0,'Break-even is when income covers costs; profit comes after that point.','उत्पन्नातून खर्च भरून निघणे म्हणजे हा टप्पा; त्यानंतर नफा होतो.'),
(10,'Why start with a small production batch?','उत्पादनाची सुरुवात छोट्या फेरीने का करावी?',JSON_ARRAY('To learn and reduce waste','To avoid checking demand','To make records unnecessary'),JSON_ARRAY('शिकण्यासाठी आणि वाया जाणे कमी करण्यासाठी','मागणी तपासणे टाळण्यासाठी','नोंदींची गरज नसण्यासाठी'),0,'A small batch limits waste while you learn what customers want.','ग्राहकांची पसंती समजताना छोटी फेरी वाया जाणे कमी करते.'),
(11,'What should clear product packaging show?','स्पष्ट उत्पादन पॅकिंगवर काय असावे?',JSON_ARRAY('Product name and useful details','An unsupported health claim','No product information'),JSON_ARRAY('उत्पादनाचे नाव आणि उपयुक्त माहिती','अप्रमाणित आरोग्यदावा','उत्पादनाची माहिती नाही'),0,'Accurate labels help customers understand what they are buying.','अचूक लेबलमुळे ग्राहकांना ते काय घेत आहेत हे समजते.'),
(12,'What makes a useful product photo?','उपयुक्त उत्पादन फोटो कसा असतो?',JSON_ARRAY('A clear view in good light','A dark photo hiding the product','Unrelated items in frame'),JSON_ARRAY('चांगल्या प्रकाशात स्पष्ट दिसणारा','उत्पादन लपवणारा अंधुक फोटो','असंबंधित वस्तू असलेला'),0,'Good light and a simple background make the product easy to see.','चांगला प्रकाश आणि साधी पार्श्वभूमी उत्पादन स्पष्ट दाखवतात.'),
(13,'What should a product message include?','उत्पादनाच्या संदेशात काय असावे?',JSON_ARRAY('Price, details and how to order','Repeated forwards only','An unverifiable promise'),JSON_ARRAY('किंमत, तपशील आणि ऑर्डरची पद्धत','फक्त वारंवार पाठवलेले संदेश','पडताळता न येणारे वचन'),0,'Customers need accurate details and a clear next step to order.','ग्राहकांना अचूक माहिती आणि ऑर्डर देण्याची स्पष्ट पद्धत हवी.'),
(14,'Which detail should never be shared to receive a UPI payment?','UPI पेमेंट मिळवण्यासाठी कोणती माहिती कधीही शेअर करू नये?',JSON_ARRAY('UPI PIN or OTP','Product name','Business hours'),JSON_ARRAY('UPI PIN किंवा OTP','उत्पादनाचे नाव','व्यवसायाची वेळ'),0,'Keep PINs and one-time passwords private; check payment in your own app.','PIN आणि OTP गुप्त ठेवा; पेमेंट तुमच्या अॅपमध्ये तपासा.'),
(15,'What is a good way to manage orders?','ऑर्डर सांभाळण्याची चांगली पद्धत कोणती?',JSON_ARRAY('Record item, price, payment and delivery date','Rely on memory only','Promise a date without checking'),JSON_ARRAY('वस्तू, किंमत, पेमेंट आणि वितरण तारीख लिहा','फक्त आठवणीवर अवलंबून राहा','तपासल्याशिवाय तारीख द्या'),0,'An order list helps confirm what was agreed and when to deliver.','ऑर्डर यादीमुळे ठरलेले तपशील आणि वितरणाची वेळ तपासता येते.'),
(16,'How can you learn from customer feedback?','ग्राहकांच्या अभिप्रायातून कसे शिकाल?',JSON_ARRAY('Listen and note useful suggestions','Argue with every customer','Ignore repeated problems'),JSON_ARRAY('ऐकून उपयोगी सूचना लिहा','प्रत्येक ग्राहकासोबत वाद घाला','वारंवार येणाऱ्या अडचणी दुर्लक्ष करा'),0,'Calmly collected feedback can reveal what to improve.','शांतपणे घेतलेल्या अभिप्रायातून काय सुधारावे हे कळते.'),
(17,'Why keep a stock record?','साठ्याची नोंद का ठेवावी?',JSON_ARRAY('Know what is available before accepting orders','Make products expire sooner','Avoid production planning'),JSON_ARRAY('ऑर्डरपूर्वी उपलब्ध साठा समजण्यासाठी','उत्पादन लवकर खराब करण्यासाठी','उत्पादन नियोजन टाळण्यासाठी'),0,'Stock records help you make realistic delivery promises and reduce waste.','साठा नोंदीमुळे वास्तव वितरणाचे वचन देता येते आणि वाया जाणे कमी होते.'),
(18,'Which is a measurable short-term goal?','मोजता येईल असे जवळच्या काळातील ध्येय कोणते?',JSON_ARRAY('Get better someday','Speak with ten customers this month','Grow a lot'),JSON_ARRAY('कधीतरी चांगले व्हायचे','या महिन्यात दहा ग्राहकांशी बोलायचे','खूप वाढायचे'),1,'A number and timeframe make a goal easier to act on and review.','संख्या आणि कालावधीमुळे ध्येयावर कृती करणे आणि आढावा घेणे सोपे होते.'),
(19,'When choosing a selling price, what should you consider?','विक्री किंमत ठरवताना काय लक्षात घ्यावे?',JSON_ARRAY('Costs, customer value and local alternatives','Only a competitor price','A price that ignores your time'),JSON_ARRAY('खर्च, ग्राहकांना मिळणारा उपयोग आणि स्थानिक पर्याय','फक्त स्पर्धकाची किंमत','तुमच्या वेळेकडे दुर्लक्ष करणारी किंमत'),0,'A fair price considers costs, customer value and your local market.','योग्य किंमतीत खर्च, ग्राहकांना मिळणारा उपयोग आणि आसपासचा बाजार लक्षात घेतला जातो.'),
(20,'What is a safe way to verify a payment?','पेमेंटची खात्री करण्याची सुरक्षित पद्धत कोणती?',JSON_ARRAY('Check your bank or UPI app','Trust any screenshot','Share your PIN with the buyer'),JSON_ARRAY('तुमचे बँक किंवा UPI अॅप तपासा','कोणताही स्क्रीनशॉट खरा माना','खरेदीदाराला PIN सांगा'),0,'Confirm the credit in your own account before handing over the order.','ऑर्डर देण्यापूर्वी तुमच्या खात्यात रक्कम जमा झाल्याची खात्री करा.')
