USE sakhibiz;

ON DUPLICATE KEY UPDATE title=VALUES(title),mr_title=VALUES(mr_title),body=VALUES(body),mr_body=VALUES(mr_body);

ON DUPLICATE KEY UPDATE title=VALUES(title),mr_title=VALUES(mr_title),category=VALUES(category),minutes=VALUES(minutes),level=VALUES(level),body=VALUES(body),mr_body=VALUES(mr_body),sort_order=VALUES(sort_order);

ON DUPLICATE KEY UPDATE question_en=VALUES(question_en),question_mr=VALUES(question_mr);

ON DUPLICATE KEY UPDATE question_en=VALUES(question_en),question_mr=VALUES(question_mr),options_en=VALUES(options_en),options_mr=VALUES(options_mr),correct_option=VALUES(correct_option),explanation_en=VALUES(explanation_en),explanation_mr=VALUES(explanation_mr);
